/// Events the bus keeps for a slow subscriber before it is told it lagged.
pub const BUS_CAPACITY: usize = 8_192;

/// Operator notifications kept on the dedicated notice channel (`Runtime::subscribe_notices`),
/// isolated from high-volume streaming `BusEvent::Delta` traffic.
pub const NOTICES_CAPACITY: usize = 256;

/// Name of the sole optional tool exposed during [`Runtime::isolated_guest_chat`].
pub const GUEST_NOTE_TOOL_NAME: &str = "leave_note_for_owner";

/// One conversational turn passed into [`Runtime::isolated_guest_chat`].
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct GuestChatTurn {
    pub role: String, // "user" or "assistant"
    pub text: String,
}

/// Reply produced by [`Runtime::isolated_guest_chat`].
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GuestChatReply {
    pub text: String,
    pub notes: Vec<String>,
    pub model_used: String,
}

/// Structured triage classification produced by [`Runtime::triage_guest_note`].
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct NoteTriage {
    pub actionable: bool,
    /// Allowlisted: "calendar", "reminder", "task", "reply", or "none".
    pub kind: String,
    /// Concise 1-line summary of the proposed action (sanitized, <= 160 chars).
    pub summary: String,
    /// Concrete instruction for a Ferret mission if the owner confirms "do" (sanitized, <= 500 chars).
    pub proposed_task: String,
    /// Optional short suggested reply to send back to the guest (sanitized, <= 240 chars).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub suggested_reply: Option<String>,
}

/// Whether a new mission decrypts HTTPS (CONTRACTS-TRAFFIC-TARGETS I1): `[network] intercept` decides
/// (`always` / `never`), else the mission's own choice, else its pack's flag.
pub fn decide_intercept(mode: &ferret_core::config::InterceptMode, pack: bool, asked: Option<bool>) -> bool {
    use ferret_core::config::InterceptMode;
    match mode {
        InterceptMode::Always => true,
        InterceptMode::Never => false,
        InterceptMode::Pack => asked.unwrap_or(pack),
    }
}

/// What the operator gives to start a session.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct NewSession {
    pub workspace: PathBuf,
    /// Pack name; absent = `core`.
    pub pack: Option<String>,
    /// Role name; absent = the pack's default role.
    pub role: Option<String>,
    /// Model profile name; absent = the config's default.
    pub model: Option<String>,
    pub title: Option<String>,
    /// Resume by itself after a restart. Absent = yes for roles that end explicitly.
    pub unattended: Option<bool>,
    pub budget: Budget,
    /// The first message, sent as soon as the session exists.
    pub message: Option<String>,
    /// Earlier missions this one may recall: what their sealed ledgers recorded is put into the lead's log
    /// once, before its first model request (`crate::prior`). Not written when empty, so that a request that
    /// names none is accepted by a daemon older than this field.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub prior: Vec<MissionId>,
    /// Model choices for the mission's agents (role → profile, [`ANY_ROLE`] for every role), set before
    /// the first message so that the lead's first agents already use them.
    pub role_models: BTreeMap<String, String>,
    /// Make `workspace` (and the folders above it that are missing) when it does not exist. The receipt of
    /// the creation says `created`; nothing is recorded in the log beyond what a session start records.
    pub create_workspace: bool,
    /// Uploads of the workspace to attach to the first message (absolute paths from `POST /api/uploads`;
    /// `docs/UPLOADS.md`). Not written when empty, so a request that names none is accepted by an older daemon.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub attachments: Vec<String>,
    /// The name of a target (`~/.ferret/targets/{name}`) the mission works on (CONTRACTS-TRAFFIC-TARGETS T2).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub target: Option<String>,
    /// The credential profile of `target` attached to the mission's in-scope requests
    /// (CONTRACTS-TRAFFIC-TARGETS S3). Refused without `target`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub creds: Option<String>,
    /// Named credential profiles of `target` mounted for multi-principal testing (`as_profile`,
    /// `http_authz_matrix`). Refused without `target`.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub creds_profiles: Vec<String>,
    /// Decrypt the mission's HTTPS (CONTRACTS-TRAFFIC-TARGETS I1): `Some(false)` turns it off for a pack that
    /// asks for it, `Some(true)` turns it on for one that does not. Absent = the pack decides. Fixed for the
    /// mission; `[network] intercept = "always"|"never"` overrides it.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub intercept: Option<bool>,
}

/// `meta.json`: what a session is, fixed when it is created.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct SessionMeta {
    pub id: SessionId,
    pub mission: MissionId,
    /// HTTPS interception is on for the mission (I1); decided once at its start, inherited by every agent.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub intercept: bool,
    #[serde(default)]
    pub parent: Option<SessionId>,
    pub workspace: String,
    /// For an agent that works in its own copy of its parent's workspace: the workspace the copy was
    /// made from. `workspace` is then the copy.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub copy_of: Option<String>,
    pub pack: String,
    pub role: String,
    /// Model profile name in the config.
    pub profile: String,
    /// Model id sent with requests.
    pub model: String,
    #[serde(default)]
    pub context_window: Option<u64>,
    #[serde(default)]
    pub title: String,
    pub created_ms: u64,
    /// How a child was started.
    #[serde(default)]
    pub mode: Option<SpawnMode>,
    /// A child whose report is returned to the call that started it.
    #[serde(default)]
    pub awaited: bool,
    #[serde(default)]
    pub unattended: bool,
    #[serde(default)]
    pub archived: bool,
    /// A verifier the finish gate of its parent started, with the assignment it was given. Its
    /// settlement belongs to that `finish`, or to a `finish` made again with the same assignment after
    /// a restart, never to the parent as an agent's report.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub gate: Option<Brief>,
    /// The earlier missions the operator chose for this one to recall, in the order given. Empty for a child.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub prior: Vec<MissionId>,
    /// A lead's model choices for its mission's agents: role → model profile, and [`ANY_ROLE`] for
    /// every role it starts. They win over the pack's when a fresh agent is started (see
    /// [`Runtime::set_role_model`]). Empty for an agent.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub role_models: BTreeMap<String, String>,
    /// The target the mission works on, as it was when the lead started (CONTRACTS-TRAFFIC-TARGETS T2):
    /// an agent inherits it, and a session restored after a restart uses this record, not the target's file.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub target: Option<ferret_core::event::TargetRef>,
    /// The credential profile the mission attaches (CONTRACTS-TRAFFIC-TARGETS S3, S11): name and summary only;
    /// an agent inherits it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub creds: Option<ferret_core::event::CredsRef>,
    /// All credential profiles mounted on a multi-principal mission (name and summary only, never values);
    /// an agent inherits them.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub creds_profiles: Vec<ferret_core::event::CredsRef>,
}

/// The key of [`SessionMeta::role_models`] that stands for every role the lead starts (`may_spawn`),
/// when the role has no choice of its own. The finish gate's verifier follows only its own.
pub const ANY_ROLE: &str = "*";

/// A session as listed.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct SessionInfo {
    #[serde(flatten)]
    pub meta: SessionMeta,
    /// A task is driving it now.
    pub active: bool,
    pub status: Status,
    /// When its log was last written (milliseconds since the epoch): the time of its latest record, so a
    /// list can order and age sessions without reading their records. Set by `Runtime::sessions`; absent
    /// elsewhere (a session event carries the record itself).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_ms: Option<u64>,
}

