    #[test]
    fn start_warns_about_a_key_held_in_the_environment() {
        let keys = std::path::Path::new("/h/keys/models");
        let mut c = Config::default();
        c.notify.command = vec!["/bin/true".into()];
        c.models.insert(
            "env".into(),
            ferret_core::config::ModelProfile { api_key_env: Some("FERRET_TEST_KEY".into()), ..Default::default() },
        );
        c.models.insert(
            "file".into(),
            ferret_core::config::ModelProfile { api_key_file: Some("file".into()), ..Default::default() },
        );
        let set = start_warnings(&c, true, keys, |v| v == "FERRET_TEST_KEY", &[]);
        assert_eq!(set.len(), 1, "{set:?}");
        assert!(set[0].contains("models.env") && set[0].contains("FERRET_TEST_KEY") && set[0].contains("can read it"));
        let unset = start_warnings(&c, true, keys, |_| false, &[]);
        assert_eq!(unset.len(), 1, "{unset:?}");
        assert!(unset[0].contains("FERRET_TEST_KEY is not set") && unset[0].contains("api_key_file"), "{unset:?}");
        assert!(set.iter().chain(&unset).all(|w| !w.contains("models.file")));
    }

