    #[tokio::test]
    async fn a_request_that_fails_after_the_folder_was_made_takes_it_back() {
        use std::os::unix::fs::PermissionsExt;
        let e = env(Script::new(|_, _| finish("ok"))).await;
        if unsafe { libc::geteuid() } == 0 {
            return;
        }
        let sessions = e.dir.path().join("home/sessions");
        std::fs::create_dir_all(&sessions).unwrap();
        std::fs::set_permissions(&sessions, std::fs::Permissions::from_mode(0o500)).unwrap();
        let made = e.dir.path().join("fresh/deeper/ws");
        let new = NewSession { workspace: made.clone(), create_workspace: true, ..NewSession::default() };
        let res = e.rt.create_session_receipt(new).await;
        std::fs::set_permissions(&sessions, std::fs::Permissions::from_mode(0o700)).unwrap();
        assert!(res.is_err(), "the session could not be written");
        assert!(!e.dir.path().join("fresh").exists(), "the folders the request made are removed");
        // What was there before stays, and a folder that has anything in it is not removed.
        let plan = plan_workspace(&Paths::at(e.dir.path().join("home")), &e.dir.path().join("keep/ws"), true).unwrap();
        let made = plan.make_tracked().unwrap();
        assert_eq!(made.created.len(), 2);
        std::fs::write(made.path.join("work.txt"), "x").unwrap();
        made.undo();
        assert!(made.path.join("work.txt").exists(), "a workspace with files is not deleted");
        std::fs::remove_file(made.path.join("work.txt")).unwrap();
        made.undo();
        assert!(!e.dir.path().join("keep").exists());
    }

    #[test]
    fn a_link_swapped_in_after_the_check_is_judged_again_once_the_folders_exist() {
        let d = tempfile::tempdir().unwrap();
        let base = std::fs::canonicalize(d.path()).unwrap();
        let home = base.join("home");
        std::fs::create_dir_all(&home).unwrap();
        std::fs::create_dir_all(base.join("elsewhere")).unwrap();
        let link = base.join("swap");
        std::os::unix::fs::symlink(&home, &link).unwrap();
        // The plan was made when `swap` led elsewhere; a plan made now is refused outright.
        assert!(plan_workspace(&Paths::at(home.clone()), &link.join("a/b"), true).is_err());
        let plan =
            WorkspacePlan::Create { path: link.join("a/b"), ancestor: base.clone(), protected: vec![home.clone()] };
        let err = plan.make_tracked().unwrap_err();
        assert!(err.contains("ferret home"), "{err}");
        assert!(!home.join("a").exists(), "what the call made inside the home is removed again");
    }

    #[tokio::test]
    async fn archive_refuses_starting_child_stops_waking_turn_and_never_deletes_live_copy() {
        // (a) Rejects archiving when a child has not ended its first turn yet.
        let stall = env(Script::new(|_, _| Action::Stall { ms: 600_000 })).await;
        let parent = stall.rt.create_session(stall.new_session(None)).await.unwrap().meta.id;
        let _kid = stall
            .rt
            .inner
            .spawn_child(
                &parent,
                SpawnReq {
                    role: "worker".into(),
                    mode: SpawnMode::Fresh,
                    brief: Brief { question: "q".into(), ..Brief::default() },
                    budget: Budget::default(),
                    call_id: CallId::from("c1"),
                    title: "starting".into(),
                    awaited: true,
                    harness: false,
                    prerequisite: None,
                    workspace: Workspace::Shared,
                },
            )
            .await
            .unwrap();
        let err = stall.rt.archive(&parent, true).await.unwrap_err();
        assert!(err.contains("Stop the session before archiving it."), "{err}");
        stall.rt.shutdown().await;

        // (b) Archiving right after an idle session is sent a waking Input::User suppresses that turn.
        let e = env(Script::new(|_, _| finish("ok"))).await;
        let id = e.rt.create_session(e.new_session(Some("first"))).await.unwrap().meta.id;
        until("idle after first turn", || {
            e.rt.session(&id).is_some_and(|s| s.status.phase == Phase::Idle && s.status.last_end.is_some())
        })
        .await;
        assert_eq!(e.server.requests().len(), 1);
        assert!(e.rt.inner.send_input(&id, Input::User("should not run".into())));
        e.rt.archive(&id, true).await.unwrap();
        until("lead closed", || e.rt.session(&id).is_some_and(|s| !s.active)).await;
        assert_eq!(e.server.requests().len(), 1, "buffered waking user turn must not run after archive");
        e.rt.shutdown().await;

        // (c) If until_closed times out with Workspace::Copy, archive returns Err and leaves the copy intact.
        let e = env_with(Script::new(|_, _| finish("ok")), false, |c| c.tools.kill_grace_s = 0).await;
        let lead = e.rt.create_session(e.new_session(None)).await.unwrap().meta.id;
        let mission = e.rt.session(&lead).unwrap().meta.mission;
        let kid = SessionId::from("s-copykid");
        let copy_dir = e.rt.paths().agent_copy(&mission, &kid);
        std::fs::create_dir_all(e.rt.paths().session_dir(&kid)).unwrap();
        std::fs::create_dir_all(&copy_dir).unwrap();
        std::fs::write(copy_dir.join("work.txt"), "keep").unwrap();
        let (closed_tx, closed_rx) = unbounded_channel();
        drop(closed_rx);
        let pending_task = tokio::spawn(std::future::pending::<()>());
        let handle = pending_task.abort_handle();
        {
            let mut st = e.rt.inner.st();
            let (shared, jobs, proxy_grant, mut meta) = {
                let lead_known = st.known.get(&lead).unwrap();
                let a = lead_known.active.as_ref().unwrap();
                (a.shared.clone(), a.jobs.clone(), a.proxy_grant.clone(), lead_known.meta.clone())
            };
            meta.id = kid.clone();
            meta.parent = Some(lead.clone());
            meta.workspace = copy_dir.display().to_string();
            meta.copy_of = Some(e.ws.display().to_string());
            let mut status = idle_status();
            status.last_end = Some(TurnEndReason::Yielded);
            let mut k = Known::new(meta, status);
            k.active = Some(ActiveSession {
                gen: 99,
                inputs: closed_tx,
                control: Arc::new(Control::new()),
                shared,
                jobs,
                proxy_grant,
                task: pending_task,
            });
            st.known.insert(kid.clone(), k);
        }
        let err = e.rt.archive(&lead, true).await.unwrap_err();
        assert!(err.contains("did not finish closing"), "{err}");
        assert!(copy_dir.join("work.txt").is_file(), "live workspace copy must not be deleted on timeout");
        handle.abort();
        e.rt.inner.st().known.get_mut(&kid).unwrap().active = None;
        e.rt.shutdown().await;
    }

    #[tokio::test]
    async fn shutdown_during_gate_verifier_retry_keeps_aborted_gate_report_inline() {
        let e = env(Script::new(|_, _| Action::Stall { ms: 600_000 })).await;
        let parent = e.rt.create_session(e.new_session(None)).await.unwrap().meta.id;
        let spawn = |harness: bool, q: &str, call_id: &str| {
            let rt = e.rt.clone();
            let p = parent.clone();
            let question = q.to_string();
            let cid = CallId::from(call_id);
            async move {
                rt.inner
                    .spawn_child(
                        &p,
                        SpawnReq {
                            role: "worker".into(),
                            mode: SpawnMode::Fresh,
                            brief: Brief { question, ..Brief::default() },
                            budget: Budget::default(),
                            call_id: cid,
                            title: "child".into(),
                            awaited: true,
                            harness,
                            prerequisite: None,
                            workspace: Workspace::Shared,
                        },
                    )
                    .await
                    .unwrap()
            }
        };
        let gate_child = spawn(true, "verify finish", "c-gate").await;
        let normal_child = spawn(false, "user child", "c-normal").await;
        let parent_shared = e.rt.inner.st().known.get(&parent).unwrap().active.as_ref().unwrap().shared.clone();
        parent_shared.emit(
            Author::Agent(gate_child.clone()),
            Event::ChildSettled(ferret_core::event::ChildSettled {
                child: gate_child.clone(),
                outcome: ChildOutcome::Stopped,
                report: "GATE_INTERNAL_REPORT".into(),
                full: None,
                usage: Usage::default(),
                steps: 1,
                inline: true,
            }),
        );
        parent_shared.emit(
            Author::Agent(normal_child.clone()),
            Event::ChildSettled(ferret_core::event::ChildSettled {
                child: normal_child.clone(),
                outcome: ChildOutcome::Returned,
                report: "NORMAL_CHILD_REPORT".into(),
                full: None,
                usage: Usage::default(),
                steps: 1,
                inline: true,
            }),
        );
        e.rt.inner.write_for_parked(&parent, &parent_shared);
        let rs = read_records(&e.rt.paths().session_log(&parent)).unwrap().records;
        let gate_rec = rs.iter().find_map(|r| match &r.event {
            Event::ChildSettled(c) if c.child == gate_child => Some(c),
            _ => None,
        });
        let normal_rec = rs.iter().find_map(|r| match &r.event {
            Event::ChildSettled(c) if c.child == normal_child => Some(c),
            _ => None,
        });
        assert!(gate_rec.unwrap().inline, "internal gate verifier must stay inline=true");
        assert!(!normal_rec.unwrap().inline, "normal child settlement flips to inline=false");
        let w = ferret_core::weave::weave(&rs);
        let rendered: String = w.messages.iter().map(|m| m.content.as_str()).collect::<Vec<_>>().join("\n");
        assert!(!rendered.contains("GATE_INTERNAL_REPORT"), "{rendered}");
        assert!(rendered.contains("NORMAL_CHILD_REPORT"), "{rendered}");
        e.rt.shutdown().await;
    }

    #[tokio::test]
    async fn reload_models_reuses_limiter_when_base_url_is_unchanged_and_replaces_when_changed() {
        let e = env(Script::new(|_, _| finish("ok"))).await;
        let file = e.rt.paths().config_file();
        let before = e.rt.inner.models().get("mock").unwrap().limiter.clone();
        assert_eq!(before.capacity(), e.config.models["mock"].max_concurrent);

        // Same base_url, different max_concurrent: reuses the exact Arc<Limiter> and updates capacity.
        let mut cfg = e.config.clone();
        cfg.models.get_mut("mock").unwrap().max_concurrent = 3;
        std::fs::write(&file, toml::to_string(&cfg).unwrap()).unwrap();
        let r = e.rt.reload_models().await.unwrap();
        assert_eq!(r.changed, vec!["mock".to_string()]);
        let same_url = e.rt.inner.models().get("mock").unwrap().limiter.clone();
        assert!(Arc::ptr_eq(&before, &same_url), "same-URL reload must reuse existing Limiter");
        assert_eq!(same_url.capacity(), 3);

        // Failed later reload must not mutate capacities on earlier same-URL profiles.
        let mut bad = cfg.clone();
        bad.models.get_mut("mock").unwrap().max_concurrent = 9;
        let mut broken = cfg.models["mock"].clone();
        broken.api_key_file = Some("missing-key-file".into());
        bad.models.insert("zzz_broken".into(), broken);
        std::fs::write(&file, toml::to_string(&bad).unwrap()).unwrap();
        assert!(e.rt.reload_models().await.is_err());
        assert_eq!(same_url.capacity(), 3, "failed reload must leave existing Limiter capacity untouched");

        // Changed base_url: constructs a new Limiter.
        let other = MockServer::start(Script::new(|_, _| finish("ok"))).await.unwrap();
        cfg.models.get_mut("mock").unwrap().base_url = other.base_url();
        std::fs::write(&file, toml::to_string(&cfg).unwrap()).unwrap();
        e.rt.reload_models().await.unwrap();
        let diff_url = e.rt.inner.models().get("mock").unwrap().limiter.clone();
        assert!(!Arc::ptr_eq(&same_url, &diff_url), "changed base_url should get its own Limiter");
        e.rt.shutdown().await;
    }

    #[tokio::test]
    async fn concurrent_create_session_undo_preserves_populated_and_sibling_workspace() {
        let e = env(Script::new(|_, _| finish("ok"))).await;
        // (a) MadeWorkspace::undo preserves `.ferret` when workspace or `.ferret` already holds files.
        let ws_a = e.dir.path().join("undo-guard/ws");
        let plan = plan_workspace(e.rt.paths(), &ws_a, true).unwrap();
        let made = plan.make_tracked().unwrap();
        std::fs::write(made.path.join("sibling.txt"), "keep").unwrap();
        made.undo();
        assert!(made.path.join(".ferret").is_dir(), "undo must not delete .ferret while workspace has entries");
        std::fs::remove_file(made.path.join("sibling.txt")).unwrap();
        std::fs::write(made.path.join(".ferret").join("secret"), "keep").unwrap();
        made.undo();
        assert!(made.path.join(".ferret").join("secret").is_file(), "undo must not fail-open on non-empty .ferret");
        std::fs::remove_file(made.path.join(".ferret").join("secret")).unwrap();
        made.undo();
        assert!(!e.dir.path().join("undo-guard").exists());

        // (b) Concurrent create_session targeting the same nonexistent path preserves its workspace and `.ferret`.
        let ws_shared = e.dir.path().join("concurrent/shared-ws");
        let mut r1 = e.new_session(None);
        r1.workspace = ws_shared.clone();
        r1.create_workspace = true;
        let mut r2 = e.new_session(None);
        r2.workspace = ws_shared.clone();
        r2.create_workspace = true;
        let (a, b) = tokio::join!(e.rt.create_session_receipt(r1), e.rt.create_session_receipt(r2));
        a.unwrap();
        b.unwrap();
        assert!(ws_shared.join(".ferret").is_dir());
        e.rt.shutdown().await;
    }

    // --- Targets (CONTRACTS-TRAFFIC-TARGETS T) ---

    fn target_body(scope: &[&str], exclude: &[&str]) -> TargetBody {
        let v = |x: &[&str]| Some(x.iter().map(|s| s.to_string()).collect::<Vec<_>>());
        TargetBody { name: Some("acme".into()), scope: v(scope), exclude: v(exclude), ..Default::default() }
    }

    fn start_of(e: &Env, id: &SessionId) -> ferret_core::event::SessionStart {
        e.records(id)
            .into_iter()
            .find_map(|r| match r.event {
                Event::SessionStart(s) => Some(s),
                _ => None,
            })
            .expect("session_start")
    }

    fn exchange(host: &str, method: &str, path: &str) -> ferret_core::event::Exchange {
        serde_json::from_value(json!({
            "id": "ex-aaaaaaaaaaaa", "source": "tool", "scheme": "https", "tls": "tool", "method": method,
            "host": host, "port": 443, "target": path,
            "request": {"id": "b-1", "bytes": 1, "lines": 1}, "request_bytes": 1, "response_bytes": 0,
            "duration_ms": 1
        }))
        .unwrap()
    }

    fn locators(e: &Env) -> Vec<(String, String)> {
        let g = e.rt.target_graph("acme", None, None, None).unwrap();
        g.nodes
            .iter()
            .map(|n| (serde_json::to_value(n.status).unwrap().as_str().unwrap().to_string(), n.locator.clone()))
            .collect()
    }

    #[tokio::test]
    async fn a_mission_with_a_target_reaches_its_scope_in_deny_all_and_never_its_exclusions() {
        let e = env(Script::new(|_, _| finish("ok"))).await;
        e.rt.target_create(&target_body(&["*.acme.test", "acme.test"], &["vpn.acme.test"])).unwrap();
        let mut new = e.new_session(Some("go"));
        new.target = Some("acme".into());
        let info = e.rt.create_session(new).await.unwrap();
        let id = info.meta.id.clone();
        let rule = |host: &str| e.rt.inner.proxy.check_name(&id, host, 443).map(|v| (v.allowed, v.rule));
        assert!(rule("www.acme.test").unwrap().0);
        assert!(!rule("vpn.acme.test").unwrap().0);
        assert!(!rule("other.test").unwrap().0);
        let start = start_of(&e, &id);
        let t = start.target.expect("target recorded");
        assert_eq!(t.name, "acme");
        assert_eq!(t.exclude, vec!["vpn.acme.test"]);
        assert!(start.system_prompt.contains("\n\n# Target acme\n"), "{}", start.system_prompt);
        // A mission without a target is unchanged: no section, nothing allowed.
        let plain = e.rt.create_session(e.new_session(Some("go"))).await.unwrap();
        let ps = start_of(&e, &plain.meta.id);
        assert!(ps.target.is_none() && !ps.system_prompt.contains("# Target"));
        assert!(!e.rt.inner.proxy.check_name(&plain.meta.id, "www.acme.test", 443).unwrap().allowed);
        // An unknown target or an invalid name is refused with a sentence.
        let mut bad = e.new_session(None);
        bad.target = Some("nope".into());
        assert!(e.rt.create_session(bad).await.unwrap_err().contains("no target"));
        e.rt.shutdown().await;
    }

    #[tokio::test]
    async fn target_graph_is_written_from_exchanges_assets_coverage_and_claims_in_scope_only() {
        use ferret_core::ledger::{Claim, ClaimStatus, LedgerOp, LedgerState};
        use ferret_core::security_state::SecurityOp;
        let e = env(Script::new(|_, _| finish("ok"))).await;
        e.rt.target_create(&target_body(&["*.acme.test", "acme.test"], &["vpn.acme.test"])).unwrap();
        let mut new = e.new_session(Some("go"));
        new.target = Some("acme".into());
        let one = e.rt.create_session(new).await.unwrap().meta.id;
        let inner = &e.rt.inner;

        // An exchange: host, service, endpoint with a path template; out of scope and excluded: nothing.
        inner.target_exchange(&one, 5, &exchange("WWW.acme.test", "get", "/users/42/orders?x=1"));
        inner.target_exchange(&one, 6, &exchange("evil.example", "GET", "/"));
        inner.target_exchange(&one, 7, &exchange("vpn.acme.test", "GET", "/"));
        let seen = locators(&e);
        let has = |l: &str| seen.iter().any(|(_, x)| x == l);
        assert!(has("www.acme.test") && has("www.acme.test:443/tcp"), "{seen:?}");
        assert!(has("GET https://www.acme.test:443/users/{id}/orders"), "{seen:?}");
        assert!(!seen.iter().any(|(_, x)| x.contains("evil") || x.contains("vpn")), "{seen:?}");

        // An asset_upsert and a coverage_set of the security state, as the ledger took them.
        let mut state = LedgerState::default();
        let ops: Vec<SecurityOp> = vec![
            serde_json::from_value(
                json!({"action":"asset_upsert","asset":{"kind":"host","locator":"api.acme.test","evidence":[]}}),
            )
            .unwrap(),
            serde_json::from_value(
                json!({"action":"asset_upsert","asset":{"kind":"host","locator":"evil.example","evidence":[]}}),
            )
            .unwrap(),
        ];
        for (i, op) in ops.iter().enumerate() {
            state.security.apply(op, i as u64 + 1, &one);
            inner.target_ledger(&one, &LedgerOp::Security(op.clone()), &state);
        }
        let api = state.security.assets.values().find(|a| a.locator == "api.acme.test").unwrap().id.clone();
        let cov: SecurityOp = serde_json::from_value(
            json!({"action":"coverage_set","asset":api,"disposition":{"status":"deferred","reason":"later"}}),
        )
        .unwrap();
        state.security.apply(&cov, 3, &one);
        inner.target_ledger(&one, &LedgerOp::Security(cov), &state);
        let g = e.rt.target_graph("acme", None, None, None).unwrap();
        let api_node = g.nodes.iter().find(|n| n.locator == "api.acme.test").expect("asset written");
        assert_eq!(serde_json::to_value(api_node.status).unwrap(), "deferred");
        assert!(!g.nodes.iter().any(|n| n.locator.contains("evil")));

        // A supported claim naming an in-scope host becomes a finding; withdrawn, it stops counting.
        state.claims.push(Claim {
            id: "c1".into(),
            text: "api.acme.test accepts any token".into(),
            status: ClaimStatus::Supported,
            note: String::new(),
            evidence: vec![],
            assets: vec![],
        });
        let upd = |status| LedgerOp::ClaimUpdate { id: "c1".into(), status, note: String::new() };
        inner.target_ledger(&one, &upd(ClaimStatus::Supported), &state);
        let status_of = || {
            let g = e.rt.target_graph("acme", None, None, None).unwrap();
            serde_json::to_value(g.nodes.iter().find(|n| n.locator == "api.acme.test").unwrap().status).unwrap()
        };
        assert_eq!(status_of(), "finding");
        state.claims[0].status = ClaimStatus::Withdrawn;
        inner.target_ledger(&one, &upd(ClaimStatus::Withdrawn), &state);
        assert_eq!(status_of(), "deferred");
        assert!(inner.target_store().verify("acme").unwrap());

        // A second mission of the target sees the first one's work at its start, and the first one's
        // recorded summary does not change.
        let before = start_of(&e, &one).target.unwrap().summary;
        let mut new = e.new_session(Some("go"));
        new.target = Some("acme".into());
        let two = e.rt.create_session(new).await.unwrap().meta.id;
        let s2 = start_of(&e, &two).target.unwrap().summary;
        assert!(s2.contains("GET https://www.acme.test:443/users/{id}/orders"), "{s2}");
        assert!(s2.contains("Known: 1 domain, 2 hosts"), "{s2}");
        assert_ne!(before, s2);
        assert_eq!(start_of(&e, &one).target.unwrap().summary, before);
        e.rt.shutdown().await;
    }

    // --- Credential profiles (CONTRACTS-TRAFFIC-TARGETS S) ---

    const SECRET: &str = "s3cr3t-session-value-9f2";

    fn cookie_item(host: &str, name: &str, value: &str) -> ferret_core::creds::Item {
        ferret_core::creds::Item {
            kind: ferret_core::creds::ItemKind::Cookie,
            name: name.into(),
            value: value.into(),
            host: host.into(),
        }
    }

    fn files_under(dir: &Path) -> Vec<PathBuf> {
        let mut out = Vec::new();
        let mut todo = vec![dir.to_path_buf()];
        while let Some(d) = todo.pop() {
            for entry in std::fs::read_dir(&d).into_iter().flatten().flatten() {
                let path = entry.path();
                if path.is_dir() {
                    todo.push(path);
                } else {
                    out.push(path);
                }
            }
        }
        out
    }

    #[tokio::test]
    async fn a_mission_with_creds_records_a_ref_and_no_value_reaches_its_session_directory() {
        let e = env(Script::new(|_, _| finish("ok"))).await;
        e.rt.target_create(&target_body(&["*.acme.test", "acme.test"], &[])).unwrap();
        e.rt.creds_set("acme", "default", vec![cookie_item("www.acme.test", "session", SECRET)]).unwrap();
        let mut new = e.new_session(Some("go"));
        new.target = Some("acme".into());
        new.creds = Some("default".into());
        let id = e.rt.create_session(new).await.unwrap().meta.id;
        let start = start_of(&e, &id);
        let c = start.creds.expect("creds recorded");
        assert_eq!(c.profile, "default");
        assert_eq!(c.dropped, 0);
        assert!(c.summary.contains("1 cookie"), "{}", c.summary);
        assert!(start.system_prompt.contains("Credential profile"), "{}", start.system_prompt);
        e.rt.shutdown().await;
        let dir = e.rt.inner.paths.session_dir(&id);
        for f in files_under(&dir) {
            let bytes = std::fs::read(&f).unwrap();
            assert!(!String::from_utf8_lossy(&bytes).contains(SECRET), "value found in {}", f.display());
        }
    }

    #[tokio::test]
    async fn creds_are_refused_without_a_target_for_an_unknown_or_invalid_profile_and_create_nothing() {
        let e = env(Script::new(|_, _| finish("ok"))).await;
        e.rt.target_create(&target_body(&["acme.test"], &[])).unwrap();
        let count = |e: &Env| files_under(&e.rt.inner.paths.home.join("sessions")).len();
        let before = count(&e);
        let mut no_target = e.new_session(Some("go"));
        no_target.creds = Some("default".into());
        assert!(e.rt.create_session(no_target).await.unwrap_err().contains("target"));
        for name in ["missing", "Bad Name"] {
            let mut new = e.new_session(Some("go"));
            new.target = Some("acme".into());
            new.creds = Some(name.into());
            let err = e.rt.create_session(new).await.unwrap_err();
            assert!(err.contains("profile"), "{err}");
        }
        assert_eq!(before, count(&e), "a refused start must create nothing");
        assert!(e.rt.sessions(true).is_empty());
        e.rt.shutdown().await;
    }

    fn tools_of(id: &SessionId) -> Arc<ferret_tools::capabilities::SessionTools> {
        lock(&SESSION_TOOLS).iter().rev().find(|(s, _)| s == id).map(|(_, t)| t.clone()).expect("session tools")
    }

    #[tokio::test]
    async fn a_target_session_gets_upstream_insecure_and_the_scope_and_one_without_a_target_gets_none() {
        let e = env(Script::new(|_, _| finish("ok"))).await;
        let mut body = target_body(&["*.acme.test", "127.0.0.1"], &["no.acme.test"]);
        body.upstream_insecure = Some(vec!["127.0.0.1".into(), "*.lab.acme.test".into()]);
        e.rt.target_create(&body).unwrap();
        let mut new = e.new_session(Some("go"));
        new.target = Some("acme".into());
        let lead = e.rt.create_session(new).await.unwrap().meta.id;
        let t = tools_of(&lead);
        assert_eq!(t.upstream_insecure.get().cloned(), Some(vec!["127.0.0.1".to_string(), "*.lab.acme.test".into()]));
        let scope = t.target_scope.get().expect("scope");
        assert!(scope.contains("www.acme.test") && !scope.contains("no.acme.test"));
        let plain = e.rt.create_session(e.new_session(Some("go"))).await.unwrap().meta.id;
        let t = tools_of(&plain);
        assert!(t.upstream_insecure.get().is_none() && t.target_scope.get().is_none());
        e.rt.shutdown().await;
    }

